   123  GF_BitStream *gf_bs_new(const u8 *buffer, u64 BufferSize, u32 mode)
   124  {
   125          GF_BitStream *tmp = (GF_BitStream *)gf_malloc(sizeof(GF_BitStream));
   126          if (!tmp) return NULL;
   127          memset(tmp, 0, sizeof(GF_BitStream));
   128
   129          tmp->original = (char*)buffer;
   130          tmp->size = BufferSize;
   131
   132          tmp->bsmode = mode;
   133
   134          switch (tmp->bsmode) {
   135          case GF_BITSTREAM_READ:
   136                  tmp->nbBits = 8;
   137                  tmp->current = 0;
   138                  break;
   139          case GF_BITSTREAM_WRITE:
   140          case GF_BITSTREAM_WRITE_DYN:
   141                  tmp->nbBits = 0;
   142                  if (! buffer) {
   143                          /*if BufferSize is specified, use it. This is typically used when AvgSize of
   144                          some buffers is known, but some exceed it.*/
   145                          if (BufferSize) {
   146                                  tmp->size = BufferSize;
   147                          } else {
   148                                  tmp->size = BS_MEM_BLOCK_ALLOC_SIZE;
   149                          }
   150                          tmp->original = (char *) gf_malloc(sizeof(char) * ((u32) tmp->size));
   151                          if (! tmp->original) {
   152                                  gf_free(tmp);
   153                                  return NULL;
   154                          }
   155                          tmp->bsmode = GF_BITSTREAM_WRITE_DYN;
   156                  } else {
   157                          tmp->original = (char*)buffer;
   158                          tmp->size = BufferSize;
   159                  }
   160                  break;
   161          default:
   162                  /*the stream constructor is not the same...*/
   163                  gf_free(tmp);
   164                  return NULL;
   165          }
   166          return tmp;
   167  }
