   170  GF_BitStream *gf_bs_from_file(FILE *f, u32 mode)
   171  {
   172          GF_BitStream *tmp;
   173          if (!f) return NULL;
   174
   175          tmp = (GF_BitStream *)gf_malloc(sizeof(GF_BitStream));
   176          if (!tmp) return NULL;
   177          memset(tmp, 0, sizeof(GF_BitStream));
   178          /*switch to internal mode*/
   179          mode = (mode==GF_BITSTREAM_READ) ? GF_BITSTREAM_FILE_READ : GF_BITSTREAM_FILE_WRITE;
   180          tmp->bsmode = mode;
   181          tmp->current = 0;
   182          tmp->nbBits = (mode == GF_BITSTREAM_FILE_READ) ? 8 : 0;
   183          tmp->original = NULL;
   184          tmp->position = 0;
   185          tmp->stream = f;
   186
   187          /*get the size of this file (for read streams)*/
   188          tmp->position = gf_ftell(f);
   189          tmp->size = gf_fsize(f);
   190          gf_fseek(f, tmp->position, SEEK_SET);
   191
   192
   193          if (mode==GF_BITSTREAM_FILE_READ) {
   194                  tmp->cache_read_alloc = gf_opts_get_int("core", "bs-cache-size");
   195                  if (tmp->cache_read_alloc) {
   196                          tmp->cache_read_pos = tmp->cache_read_size = tmp->cache_read_alloc;
   197                          tmp->cache_read = gf_malloc(tmp->cache_read_alloc);
   198                          if (!tmp->cache_read) {
   199                                  gf_free(tmp);
   200                                  return NULL;
   201                          }
   202                  }
   203          }
   204          if (mode == GF_BITSTREAM_FILE_WRITE) {
   205                  tmp->cache_write_size = gf_opts_get_int("core", "bs-cache-size");
   206                  if (tmp->cache_write_size) {
   207                          tmp->cache_write = (char*)gf_malloc(tmp->cache_write_size);
   208                          if (!tmp->cache_write) {
   209                                  gf_free(tmp);
   210                                  return NULL;
   211                          }
   212                          tmp->buffer_written = 0;
   213                  }
   214          }
   215
   216          return tmp;
   217  }
